package com.example.application_service.service;import com.example.application_service.entity.*;import com.example.application_service.repository.OutboxEventRepository;import org.slf4j.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.data.domain.PageRequest;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.transaction.PlatformTransactionManager;import java.time.*;import java.util.*;
@Component @ConditionalOnProperty(name="application-service.outbox.enabled",havingValue="true",matchIfMissing=true) public class OutboxPublisher{private static final Logger log=LoggerFactory.getLogger(OutboxPublisher.class);private final OutboxEventRepository outbox;private final ConfirmedEventSender sender;private final TransactionTemplate tx;private final String exchange,submitted,statusChanged;private final int batch,maxAttempts;public OutboxPublisher(OutboxEventRepository o,ConfirmedEventSender sender,PlatformTransactionManager tm,@Value("${application-service.messaging.exchange}")String exchange,@Value("${application-service.messaging.submitted-routing-key}")String submitted,@Value("${application-service.messaging.status-routing-key}")String changed,@Value("${application-service.outbox.batch-size}")int batch,@Value("${application-service.outbox.max-attempts}")int max){outbox=o;this.sender=sender;tx=new TransactionTemplate(tm);this.exchange=exchange;this.submitted=submitted;statusChanged=changed;this.batch=batch;maxAttempts=max;}
 @Scheduled(fixedDelayString="${application-service.outbox.fixed-delay:1000}")public void publishReady(){for(OutboxEvent event:claim())publish(event);}
 List<OutboxEvent> claim(){return tx.execute(s->{var rows=outbox.lockBatch(List.of(OutboxStatus.PENDING,OutboxStatus.FAILED),OutboxStatus.IN_PROGRESS,Instant.now(),Instant.now().minusSeconds(60),PageRequest.of(0,batch));rows.forEach(OutboxEvent::claim);return List.copyOf(rows);});}
 void publish(OutboxEvent event){try{sender.send(exchange,routing(event),event);tx.executeWithoutResult(s->outbox.findById(event.getId()).ifPresent(OutboxEvent::published));}catch(Exception e){log.warn("outbox_publish_failed eventId={} applicationId={} type={}",event.getId(),event.getAggregateId(),e.getClass().getSimpleName());tx.executeWithoutResult(s->outbox.findById(event.getId()).ifPresent(x->x.failed(e.getClass().getSimpleName(),maxAttempts)));}}
 private String routing(OutboxEvent e){return "APPLICATION_SUBMITTED".equals(e.getEventType())?submitted:statusChanged;}}
